-- Draft schema, validated locally. Apply as a versioned migration after project selection.
create table public.stores (id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references auth.users(id), name text not null check(length(name) between 2 and 120), created_at timestamptz not null default now());
create table public.members (store_id uuid references stores(id), user_id uuid references auth.users(id), role text not null check(role in ('admin','gerente','vendedor','financeiro','tecnico')), primary key(store_id,user_id));
create table public.customers (id uuid primary key default gen_random_uuid(), store_id uuid not null references stores(id), name text not null check(length(name) between 2 and 120), document text, phone text not null default '', email text not null default '', address text not null default '', notes text not null default '', active boolean not null default true, created_at timestamptz not null default now(), unique(store_id,id), unique(store_id,document));
create table public.devices (id uuid primary key default gen_random_uuid(), store_id uuid not null references stores(id), brand text not null, model text not null, color text not null default '', storage text not null default '', imei text not null check(imei ~ '^[0-9]{15}$'), imei2 text check(imei2 ~ '^[0-9]{15}$'), serial text not null default '', condition text not null check(condition in ('Novo','Seminovo','Usado','Recondicionado')), battery int check(battery between 0 and 100), purchase_cents bigint not null check(purchase_cents>=0), repair_cents bigint not null default 0 check(repair_cents>=0), price_cents bigint not null check(price_cents>0), origin text not null, origin_invoice text not null default '', inspection text not null default '', warranty_days int not null default 90 check(warranty_days>=0), status text not null default 'Disponível' check(status in ('Disponível','Vendido','Em manutenção')), created_at timestamptz not null default now(), unique(store_id,imei), unique(store_id,id));
create table public.purchases (id uuid primary key default gen_random_uuid(), store_id uuid not null, device_id uuid not null, seller text not null, amount_cents bigint not null check(amount_cents>=0), paid boolean not null default false, due_date date not null, created_at timestamptz not null default now(), foreign key(store_id,device_id) references devices(store_id,id), unique(store_id,id));
create table public.sales (id uuid primary key default gen_random_uuid(), store_id uuid not null references stores(id), customer_id uuid not null, number bigint generated always as identity, subtotal_cents bigint not null check(subtotal_cents>0), discount_cents bigint not null default 0 check(discount_cents>=0 and discount_cents<subtotal_cents), total_cents bigint generated always as (subtotal_cents-discount_cents) stored, status text not null default 'Ativa' check(status in ('Ativa','Cancelada')), notes text not null default '', created_at timestamptz not null default now(), created_by uuid not null default auth.uid(), foreign key(store_id,customer_id) references customers(store_id,id), unique(store_id,id));
create table public.sale_items (id uuid primary key default gen_random_uuid(), store_id uuid not null, sale_id uuid not null, device_id uuid not null, label text not null, imei text not null, price_cents bigint not null check(price_cents>0), cost_cents bigint not null check(cost_cents>=0), foreign key(store_id,sale_id) references sales(store_id,id), foreign key(store_id,device_id) references devices(store_id,id), unique(sale_id,device_id));
create table public.installments (id uuid primary key default gen_random_uuid(), store_id uuid not null, sale_id uuid not null, number int not null check(number>0), due_date date not null, amount_cents bigint not null check(amount_cents>0), canceled boolean not null default false, foreign key(store_id,sale_id) references sales(store_id,id), unique(store_id,id));
create table public.receipts (id uuid primary key default gen_random_uuid(), store_id uuid not null, sale_id uuid not null, installment_id uuid, amount_cents bigint not null check(amount_cents<>0), method text not null check(method in ('PIX','Dinheiro','Débito','Crédito','Transferência','Estorno')), reversal_of uuid unique references receipts(id), created_at timestamptz not null default now(), created_by uuid not null default auth.uid(), foreign key(store_id,sale_id) references sales(store_id,id), foreign key(store_id,installment_id) references installments(store_id,id), unique(store_id,id), check((amount_cents>0 and reversal_of is null and method<>'Estorno') or (amount_cents<0 and reversal_of is not null and method='Estorno')));
create table public.ledger (id uuid primary key default gen_random_uuid(), store_id uuid not null references stores(id), amount_cents bigint not null check(amount_cents<>0), description text not null, receipt_id uuid unique, purchase_id uuid unique, method text not null, created_at timestamptz not null default now(), created_by uuid not null default auth.uid(), foreign key(store_id,receipt_id) references receipts(store_id,id), foreign key(store_id,purchase_id) references purchases(store_id,id));
create index customers_store_idx on customers(store_id); create index devices_store_idx on devices(store_id,status); create index sales_store_idx on sales(store_id,created_at); create index installments_store_idx on installments(store_id,due_date); create index receipts_sale_idx on receipts(sale_id); create index ledger_store_idx on ledger(store_id,created_at); create index sale_items_store_idx on sale_items(store_id); create index purchases_store_idx on purchases(store_id);
-- Membership lookups read only a user's own row; no recursive store policies.
alter table stores enable row level security; alter table members enable row level security;
create policy members_self on members for select to authenticated using(user_id=(select auth.uid()));
create function public.can_access(s uuid, roles text[] default array['admin','gerente','vendedor','financeiro','tecnico']) returns boolean language sql stable security invoker set search_path='' as $$ select exists(select 1 from public.members where store_id=s and user_id=(select auth.uid()) and role=any(roles)) $$;
create policy store_read on stores for select to authenticated using(owner_id=(select auth.uid()) or public.can_access(id));
create policy store_insert on stores for insert to authenticated with check(owner_id=(select auth.uid()));
create policy owner_member on members for insert to authenticated with check(user_id=(select auth.uid()) and role='admin' and exists(select 1 from stores where id=store_id and owner_id=(select auth.uid())));
-- Only transaction functions may modify accounting and stock.
do $$ declare t text; begin foreach t in array array['customers','devices','purchases','sales','sale_items','installments','receipts','ledger'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy read_store on public.%I for select to authenticated using(public.can_access(store_id))',t); end loop; end $$;
create policy customer_insert on customers for insert to authenticated with check(public.can_access(store_id,array['admin','gerente','vendedor']));
create policy customer_update on customers for update to authenticated using(public.can_access(store_id,array['admin','gerente','vendedor'])) with check(public.can_access(store_id,array['admin','gerente','vendedor']));
do $$ declare t text; begin foreach t in array array['devices','purchases','sales','sale_items','installments','receipts','ledger'] loop execute format('create policy transaction_insert on public.%I for insert to authenticated with check(public.can_access(store_id,array[''admin'',''gerente'',''vendedor'',''financeiro'']) and current_setting(''ultra.transaction'',true)=''yes'')',t); end loop; foreach t in array array['devices','purchases','sales','installments'] loop execute format('create policy transaction_update on public.%I for update to authenticated using(public.can_access(store_id,array[''admin'',''gerente'',''vendedor'',''financeiro'']) and current_setting(''ultra.transaction'',true)=''yes'') with check(public.can_access(store_id,array[''admin'',''gerente'',''vendedor'',''financeiro'']) and current_setting(''ultra.transaction'',true)=''yes'')',t); end loop; end $$;
create function public.check_imei(v text) returns boolean language plpgsql immutable set search_path='' as $$ declare i int; d int; n int:=0; begin if v !~ '^[0-9]{15}$' then return false; end if; for i in 1..15 loop d:=substring(v,i,1)::int; if i%2=0 then d:=d*2; end if; n:=n+(d/10)+(d%10); end loop; return n%10=0; end $$;
alter table devices add check(public.check_imei(imei)); alter table devices add check(imei2 is null or public.check_imei(imei2));
create function public.bootstrap_store(p_name text) returns uuid language plpgsql security invoker set search_path='' as $$ declare s uuid; begin if auth.uid() is null then raise exception 'Entre na sua conta.'; end if; insert into public.stores(name) values(p_name) returning id into s; insert into public.members values(s,auth.uid(),'admin'); return s; end $$;
create function public.intake_device(p_store uuid,p_device jsonb,p_seller text,p_paid boolean,p_due date,p_method text,p_request uuid) returns uuid language plpgsql security invoker set search_path='' as $$ declare d uuid; cost bigint; begin if not public.can_access(p_store,array['admin','gerente']) then raise exception 'Sem permissão para compras.'; end if; if exists(select 1 from public.purchases where id=p_request and store_id=p_store) then select device_id into d from public.purchases where id=p_request and store_id=p_store; return d; end if; if length(trim(p_seller))<2 or p_due is null then raise exception 'Informe vendedor e vencimento.'; end if; if p_paid and p_method not in ('PIX','Dinheiro','Débito','Crédito','Transferência') then raise exception 'Forma de pagamento inválida.'; end if; perform set_config('ultra.transaction','yes',true); cost:=(p_device->>'purchase_cents')::bigint;
insert into public.devices(store_id,brand,model,color,storage,imei,imei2,serial,condition,battery,purchase_cents,repair_cents,price_cents,origin,origin_invoice,inspection,warranty_days) values(p_store,p_device->>'brand',p_device->>'model',coalesce(p_device->>'color',''),coalesce(p_device->>'storage',''),p_device->>'imei',nullif(p_device->>'imei2',''),coalesce(p_device->>'serial',''),p_device->>'condition',nullif(p_device->>'battery','')::int,cost,coalesce((p_device->>'repair_cents')::bigint,0),(p_device->>'price_cents')::bigint,p_seller,coalesce(p_device->>'origin_invoice',''),coalesce(p_device->>'inspection',''),coalesce((p_device->>'warranty_days')::int,90)) returning id into d;
insert into public.purchases(id,store_id,device_id,seller,amount_cents,paid,due_date) values(p_request,p_store,d,p_seller,cost,p_paid,p_due);
if p_paid and cost>0 then insert into public.ledger(store_id,amount_cents,description,purchase_id,method) values(p_store,-cost,'Compra de aparelho',p_request,p_method); end if; return d; end $$;
create function public.make_sale(p_store uuid,p_customer uuid,p_devices uuid[],p_discount bigint,p_entry bigint,p_count int,p_first_due date,p_method text,p_notes text,p_request uuid) returns uuid language plpgsql security invoker set search_path='' as $$ declare d public.devices; subtotal bigint:=0; sid uuid:=p_request; remaining bigint; i int; base bigint; extra bigint; due date; r uuid; begin if not public.can_access(p_store,array['admin','gerente','vendedor']) then raise exception 'Sem permissão para vender.'; end if; perform set_config('ultra.transaction','yes',true); if exists(select 1 from public.sales where id=sid and store_id=p_store) then return sid; end if; if p_devices is null or cardinality(p_devices)<1 or cardinality(p_devices)>50 or cardinality(p_devices)<>(select count(distinct x) from unnest(p_devices) x) then raise exception 'Selecione aparelhos distintos.'; end if;
if not exists(select 1 from public.customers where id=p_customer and store_id=p_store and active) then raise exception 'Cliente inválido.'; end if;
for d in select * from public.devices where store_id=p_store and id=any(p_devices) order by id for update loop if d.status<>'Disponível' then raise exception 'Aparelho indisponível: %',d.model; end if; subtotal:=subtotal+d.price_cents; end loop;
if (select count(*) from public.devices where store_id=p_store and id=any(p_devices))<>cardinality(p_devices) then raise exception 'Aparelho não encontrado.'; end if;
if p_discount is null or p_discount<0 or p_discount>=subtotal or p_entry is null or p_entry<0 or p_entry>subtotal-p_discount then raise exception 'Valores inválidos.'; end if;
remaining:=subtotal-p_discount-p_entry; if remaining>0 and (p_count is null or p_count<1 or p_count>36 or remaining<p_count or p_first_due is null) then raise exception 'Parcelamento inválido.'; end if; if p_entry>0 and p_method not in ('PIX','Dinheiro','Débito','Crédito','Transferência') then raise exception 'Forma de pagamento inválida.'; end if;
perform set_config('ultra.transaction','yes',true);
insert into public.sales(id,store_id,customer_id,subtotal_cents,discount_cents,notes) values(sid,p_store,p_customer,subtotal,p_discount,coalesce(p_notes,''));
insert into public.sale_items(store_id,sale_id,device_id,label,imei,price_cents,cost_cents) select p_store,sid,id,brand||' '||model||' '||storage,imei,price_cents,purchase_cents+repair_cents from public.devices where store_id=p_store and id=any(p_devices);
update public.devices set status='Vendido' where store_id=p_store and id=any(p_devices);
if p_entry>0 then insert into public.receipts(store_id,sale_id,amount_cents,method) values(p_store,sid,p_entry,p_method) returning id into r; insert into public.ledger(store_id,amount_cents,description,receipt_id,method) values(p_store,p_entry,'Entrada da venda',r,p_method); end if;
if remaining>0 then base:=remaining/p_count; extra:=remaining%p_count; for i in 1..p_count loop due:=(date_trunc('month',p_first_due)+(i-1)*interval '1 month')::date; due:=due+(least(extract(day from p_first_due)::int,extract(day from (due+interval '1 month - 1 day'))::int)-1); insert into public.installments(store_id,sale_id,number,due_date,amount_cents) values(p_store,sid,i,due,base+case when i<=extra then 1 else 0 end); end loop; end if; return sid; end $$;
create function public.receive_installment(p_installment uuid,p_amount bigint,p_method text,p_request uuid) returns uuid language plpgsql security invoker set search_path='' as $$ declare x public.installments; paid bigint; begin perform set_config('ultra.transaction','yes',true); select * into x from public.installments where id=p_installment for update; if x.id is null or not public.can_access(x.store_id,array['admin','gerente','financeiro']) then raise exception 'Parcela não encontrada ou sem permissão.'; end if; if exists(select 1 from public.receipts where id=p_request and store_id=x.store_id) then return p_request; end if; if x.canceled or not exists(select 1 from public.sales where id=x.sale_id and status='Ativa') then raise exception 'Venda cancelada.'; end if; select coalesce(sum(amount_cents),0) into paid from public.receipts where installment_id=x.id; if p_amount is null or p_amount<=0 or p_amount>x.amount_cents-paid then raise exception 'Valor superior ao saldo ou inválido.'; end if; if p_method not in ('PIX','Dinheiro','Débito','Crédito','Transferência') then raise exception 'Forma de pagamento inválida.'; end if; perform set_config('ultra.transaction','yes',true); insert into public.receipts(id,store_id,sale_id,installment_id,amount_cents,method) values(p_request,x.store_id,x.sale_id,x.id,p_amount,p_method); insert into public.ledger(store_id,amount_cents,description,receipt_id,method) values(x.store_id,p_amount,'Recebimento de parcela',p_request,p_method); return p_request; end $$;
create function public.pay_purchase(p_purchase uuid,p_method text) returns void language plpgsql security invoker set search_path='' as $$ declare x public.purchases; begin perform set_config('ultra.transaction','yes',true); select * into x from public.purchases where id=p_purchase for update; if x.id is null or not public.can_access(x.store_id,array['admin','gerente','financeiro']) then raise exception 'Sem permissão.'; end if; if x.paid then return; end if; if p_method not in ('PIX','Dinheiro','Débito','Crédito','Transferência') then raise exception 'Forma de pagamento inválida.'; end if; perform set_config('ultra.transaction','yes',true); update public.purchases set paid=true where id=x.id; if x.amount_cents>0 then insert into public.ledger(store_id,amount_cents,description,purchase_id,method) values(x.store_id,-x.amount_cents,'Pagamento da compra',x.id,p_method); end if; end $$;
create function public.cancel_sale(p_sale uuid,p_reason text) returns void language plpgsql security invoker set search_path='' as $$ declare s public.sales; r public.receipts; rid uuid; begin perform set_config('ultra.transaction','yes',true); select * into s from public.sales where id=p_sale for update; if s.id is null or not public.can_access(s.store_id,array['admin','gerente']) then raise exception 'Sem permissão para cancelar.'; end if; if s.status='Cancelada' then return; end if; if length(trim(p_reason))<5 then raise exception 'Informe o motivo do cancelamento.'; end if;
-- Lock installments in the same order as receiving before touching receipts.
perform 1 from public.installments where sale_id=s.id order by id for update;
perform set_config('ultra.transaction','yes',true); for r in select * from public.receipts where sale_id=s.id and amount_cents>0 and not exists(select 1 from public.receipts rr where rr.reversal_of=receipts.id) loop insert into public.receipts(store_id,sale_id,installment_id,amount_cents,method,reversal_of) values(s.store_id,s.id,r.installment_id,-r.amount_cents,'Estorno',r.id) returning id into rid; insert into public.ledger(store_id,amount_cents,description,receipt_id,method) values(s.store_id,-r.amount_cents,'Cancelamento: '||p_reason,rid,'Estorno'); end loop;
update public.installments set canceled=true where sale_id=s.id; update public.devices set status='Disponível' where store_id=s.store_id and id in(select device_id from public.sale_items where sale_id=s.id); update public.sales set status='Cancelada',notes=notes||E'\nCancelamento: '||p_reason where id=s.id; end $$;
-- No deletes on fiscal/financial entities; transactions preserve original entries.
grant select on stores,members,customers,devices,purchases,sales,sale_items,installments,receipts,ledger to authenticated;
grant insert on stores,members,customers,devices,purchases,sales,sale_items,installments,receipts,ledger to authenticated;
grant update on customers,devices,purchases,sales,installments to authenticated;
grant usage,select on all sequences in schema public to authenticated;
revoke all on function public.bootstrap_store(text),public.intake_device(uuid,jsonb,text,boolean,date,text,uuid),public.make_sale(uuid,uuid,uuid[],bigint,bigint,int,date,text,text,uuid),public.receive_installment(uuid,bigint,text,uuid),public.pay_purchase(uuid,text),public.cancel_sale(uuid,text) from public,anon;
grant execute on function public.bootstrap_store(text),public.intake_device(uuid,jsonb,text,boolean,date,text,uuid),public.make_sale(uuid,uuid,uuid[],bigint,bigint,int,date,text,text,uuid),public.receive_installment(uuid,bigint,text,uuid),public.pay_purchase(uuid,text),public.cancel_sale(uuid,text),public.can_access(uuid,text[]),public.check_imei(text) to authenticated;
-- Append-only audit trail; the internal trigger alone may write it.
create schema if not exists ultra_private;
create table public.audit_events(id uuid primary key default gen_random_uuid(),store_id uuid not null references stores(id),actor_id uuid not null references auth.users(id),entity text not null,entity_id uuid not null,operation text not null,before_data jsonb,after_data jsonb,created_at timestamptz not null default now());
alter table public.audit_events enable row level security;
create policy audit_read on audit_events for select to authenticated using(public.can_access(store_id,array['admin','gerente']));
create index audit_store_idx on audit_events(store_id,created_at);
revoke all on audit_events from anon,authenticated;grant select on audit_events to authenticated;
create function ultra_private.record_audit() returns trigger language plpgsql security definer set search_path='' as $$ declare s uuid; rid uuid; b jsonb; a jsonb; begin if auth.uid() is null then raise exception 'Ator autenticado obrigatório.'; end if; if TG_OP='UPDATE' then b:=to_jsonb(old); end if; a:=to_jsonb(new);s:=(a->>'store_id')::uuid;rid:=(a->>'id')::uuid;if not public.can_access(s) then raise exception 'Sem acesso à loja.';end if;insert into public.audit_events(store_id,actor_id,entity,entity_id,operation,before_data,after_data) values(s,auth.uid(),TG_TABLE_NAME,rid,TG_OP,b,a);return new;end $$;
revoke all on function ultra_private.record_audit() from public,anon,authenticated;
do $$ declare t text; begin foreach t in array array['customers','devices','purchases','sales','sale_items','installments','receipts','ledger'] loop execute format('create trigger audit_changes after insert or update on public.%I for each row execute function ultra_private.record_audit()',t);end loop;end $$;
-- Financial visibility follows each user's role, rather than authentication alone.
do $$ declare t text; begin foreach t in array array['purchases','ledger'] loop execute format('drop policy read_store on public.%I',t);execute format('create policy read_store on public.%I for select to authenticated using(public.can_access(store_id,array[''admin'',''gerente'',''financeiro'']))',t);end loop;foreach t in array array['sales','sale_items','installments','receipts'] loop execute format('drop policy read_store on public.%I',t);execute format('create policy read_store on public.%I for select to authenticated using(public.can_access(store_id,array[''admin'',''gerente'',''vendedor'',''financeiro'']))',t);end loop;end $$;
create function public.check_cpf(v text) returns boolean language plpgsql immutable set search_path='' as $$ declare size int;i int;sum int;d int;begin if v !~ '^[0-9]{11}$' or v ~ '^([0-9])\1{10}$' then return false;end if;for size in 9..10 loop sum:=0;for i in 1..size loop sum:=sum+substring(v,i,1)::int*(size+2-i);end loop;d:=(sum*10)%11%10;if d<>substring(v,size+1,1)::int then return false;end if;end loop;return true;end $$;
alter table customers add check(document is null or public.check_cpf(document));
alter table customers add check(length(trim(name))>=2);
alter table devices add check(length(trim(brand))>0 and length(trim(model))>0);
